EDITS = {'src/App.tsx': [("const TerminalAutomation = lazy(() => import('./pages/terminal/TerminalAutomation'));", "const TerminalAutomation = lazy(() => import('./pages/terminal/TerminalAutomation'));\nconst TerminalPlaybook = lazy(() => import('./pages/terminal/TerminalPlaybook'));"), ('                <TerminalAutomation />\n              </TerminalLayout>\n            </AuthCheck>\n        </QueryProvider>\n      ),\n    },', '                <TerminalAutomation />\n              </TerminalLayout>\n            </AuthCheck>\n        </QueryProvider>\n      ),\n    },\n    {\n      path: "/terminal/playbook",\n      element: (\n        <QueryProvider>\n            <AuthCheck>\n              <TerminalLayout>\n                <TerminalPlaybook />\n              </TerminalLayout>\n            </AuthCheck>\n        </QueryProvider>\n      ),\n    },')], 'src/components/terminal/TerminalSidebar.tsx': [("  Keyboard,\n  TerminalSquare,\n} from 'lucide-react';", "  Keyboard,\n  TerminalSquare,\n  BookOpen,\n} from 'lucide-react';"), ("import { useTerminalAuth } from '@/hooks/useTerminalAuth';", "import { useTerminalAuth } from '@/hooks/useTerminalAuth';\nimport { useCopilotAccess } from '@/hooks/useCopilotPlaybook';"), ('  requiredPermission?: TerminalPermission;\n  comingSoon?: boolean;\n}', '  requiredPermission?: TerminalPermission;\n  comingSoon?: boolean;\n  /** Shown only to Copilot approvers (copilot_my_access); the count is their open Playbook inbox. */\n  copilotApproversOnly?: boolean;\n}'), ("  { title: 'Automation', url: '/terminal/automation', icon: Bot, tone: 'info', requiredPermission: 'terminal_pricing_view' },", "  { title: 'Automation', url: '/terminal/automation', icon: Bot, tone: 'info', requiredPermission: 'terminal_pricing_view' },\n  { title: 'Playbook', url: '/terminal/playbook', icon: BookOpen, tone: 'primary', copilotApproversOnly: true },"), ('  const { hasPermission } = useTerminalAuth();\n', '  const { hasPermission } = useTerminalAuth();\n  const { data: copilotAccess } = useCopilotAccess();\n'), ('  const visibleItems = navItems.filter((item) => {\n    if (!item.requiredPermission) return true;', '  const visibleItems = navItems.filter((item) => {\n    if (item.copilotApproversOnly) return !!copilotAccess?.is_approver;\n    if (!item.requiredPermission) return true;'), ('    if (item.showAppealPendingCount) return pendingAppealCheckInCount;', '    if (item.showAppealPendingCount) return pendingAppealCheckInCount;\n    if (item.copilotApproversOnly) return copilotAccess?.open_inbox ?? 0;')]}
STATE_LINES = ["- {IST}: CP-3 — Terminal Copilot v2 Playbook page for approvers (/terminal/playbook; sidebar item with the open-inbox count, approvers only): Inbox (conflicts: keep new / existing / both; tentative replies: approve, edit, reject, skip; keys A E R S N O B, guarded against typing, dialogs and g-then-letter shortcuts), Entries (search, filters, edit sheet with English/Hindi replies, phrasings, where it applies, version history with restore), Stats (coverage, model comparison, spend by day, recent saves), Settings. Migration: copilot_add_question, copilot_inbox_decide, copilot_set_entry_status (entry and its inbox items change together), copilot_stats, copilot_pending_questions, copilot_set_question_embeddings, and the one-time tentative seed (23 replies, 143 phrasings; approvers only; trial ends after 60 days unless used). copilot-draft embeds new phrasings alongside an approver's chat lookup (no background job); embeddings kept in input order. Operators unchanged."]

def sha(b):
    return hashlib.sha256(b).hexdigest()

def read(path):
    with open(path, "rb") as fh:
        return fh.read()

def main():
    problems = []
    if not os.path.isdir("supabase/functions") or not os.path.isdir("src"):
        problems.append("run this from the project root")
    plan = []  # (path, new bytes or None for delete)
    for path, (digest, lines) in NEW.items():
        data = _b(lines)
        if sha(data) != digest:
            problems.append(f"embedded content for {path} is damaged")
        if os.path.exists(path):
            if sha(read(path)) == digest:
                continue
            problems.append(f"{path} already exists with other content")
        plan.append((path, data))
    for path, (old_digest, new_digest, lines) in REPLACE.items():
        data = _b(lines)
        if sha(data) != new_digest:
            problems.append(f"embedded content for {path} is damaged")
        if not os.path.isfile(path):
            problems.append(f"{path} is missing")
            continue
        current = sha(read(path))
        if current == new_digest:
            continue
        if current != old_digest:
            problems.append(f"{path} changed since commit c9c2992 (sha256 {current[:12]}); not overwriting someone else's edit")
            continue
        plan.append((path, data))
    for path, old_digest in DELETE.items():
        if not os.path.exists(path):
            continue
        current = sha(read(path))
        if current != old_digest:
            problems.append(f"{path} changed since commit c9c2992 (sha256 {current[:12]}); not deleting it")
            continue
        plan.append((path, None))
    edited = {}  # path -> (old text, new text)
    for path, edits in EDITS.items():
        if not os.path.isfile(path):
            problems.append(f"{path} is missing")
            continue
        text = read(path).decode("utf-8")
        new_text = text
        for old, new in edits:
            if new in new_text:
                continue  # already applied
            if new_text.count(old) != 1:
                problems.append(f"{path}: expected exactly one place for an insertion (found {new_text.count(old)}); not editing it")
                break
            new_text = new_text.replace(old, new)
        if new_text != text:
            edited[path] = (text, new_text)
    log = "docs/STATE_LOG.md"
    log_text = read(log).decode("utf-8") if os.path.isfile(log) else None
    if log_text is None:
        problems.append("docs/STATE_LOG.md not found")
    if problems:
        print("NOT APPLIED:\n- " + "\n- ".join(problems))
        sys.exit(1)

    ist = datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=5, minutes=30))).strftime("%Y-%m-%d %H:%M IST")
    add = [l.replace("{IST}", ist) for l in STATE_LINES if (": " + l.split(": ", 1)[1].split(" — ")[0] + " — ") not in log_text]
    backups = {}
    removed_dirs = []
    try:
        for path, data in plan:
            backups[path] = read(path) if os.path.exists(path) else None
            if data is None:
                os.remove(path)
                d = os.path.dirname(path)
                if d.startswith("supabase/functions/copilot-") and os.path.isdir(d) and not os.listdir(d):
                    os.rmdir(d)
                    removed_dirs.append(d)
            else:
                os.makedirs(os.path.dirname(path), exist_ok=True)
                with open(path, "wb") as fh:
                    fh.write(data)
        for path, (old_text, new_text) in edited.items():
            backups[path] = old_text.encode("utf-8")
            with open(path, "w", encoding="utf-8") as fh:
                fh.write(new_text)
        if add:
            backups[log] = log_text.encode("utf-8")
            with open(log, "w", encoding="utf-8") as fh:
                fh.write(log_text.rstrip("\n") + "\n" + "\n".join(add) + "\n")
    except Exception as exc:
        for d in removed_dirs:
            os.makedirs(d, exist_ok=True)
        for path, data in backups.items():
            if data is None:
                try: os.remove(path)
                except OSError: pass
            else:
                os.makedirs(os.path.dirname(path), exist_ok=True)
                with open(path, "wb") as fh:
                    fh.write(data)
        print(f"NOT APPLIED: write failed ({exc}); everything restored")
        sys.exit(1)
    written = [p for p, d in plan if d is not None]
    deleted = [p for p, d in plan if d is None]
    print(f"OK: {len(written)} files written, {len(edited)} edited ({', '.join(sorted(edited)) or 'already done'}), STATE_LOG +{len(add)} line(s)")
    for path in sorted(list(NEW) + list(REPLACE)):
        print(f"  {sha(read(path))[:16]}  {path}")

main()
